  (* [comment removed for export] *)
  Definition shb_cells_check (A : Z) (cs : list cell) : bool :=
    cells_wfb cs && Z.leb (SHOFF + 0x10000 / 8) A && Z.leb (A + Z.of_nat (cells_size cs)) (SHOFF + 0x684000 / 8)
    && bytes_check (CAbs, A) (cellsZ cs).
